DELETE FROM analytics_dashboard_card
 WHERE dashboard_id IN (
           SELECT id
             FROM analytics_dashboard
            WHERE name LIKE 'Sprint27 IT08 看板%'
               OR description = 'Sprint-27 IT08 live pin dashboard'
       );

DELETE FROM analytics_dashboard
 WHERE name LIKE 'Sprint27 IT08 看板%'
    OR description = 'Sprint-27 IT08 live pin dashboard';
